// lib/partners/leptos.text.ts: every text of the Leptos profile, in all seven editions (en, de, el, pl, ro, ru, ar).
//
// Rules this file follows:
//  • Facts come from the company workbook, the public pages of leptosestates.com and Daniel's "12 reasons" text. No price, no
//    date, no number that is not in those sources.
//  • What Leptos says about itself is written as the company's statement (the section notes say so); we do not vouch for it.
//  • Personal names, brand names and project names stay in Latin script; place names are localised.
//  • No long dashes in running text (house style). Pure data, no I/O.
import type { L7 } from '@/lib/partners/types';
import type { AreaKey, FeatureKey, KindKey, PlaceKey, SectorKey } from '@/lib/partners/leptos.data';

const L = (en: string, de: string, el: string, pl: string, ro: string, ru: string, ar: string): L7 => ({ en, de, el, pl, ro, ru, ar });

// ── the summary stored in directory_listings.summary_<locale> for the head office ───────────────────
export const HUB_SUMMARY: L7 = L(
  'Leptos Estates is the luxury property developer of the Leptos Group, a Cypriot family company active since 1960. Headquartered in Paphos with offices in Nicosia and Limassol, it builds villas, seafront residences and resorts in Cyprus and Greece.',
  'Leptos Estates ist der Luxus-Projektentwickler der Leptos Group, eines zypriotischen Familienunternehmens, das seit 1960 besteht. Mit Hauptsitz in Paphos und Büros in Nikosia und Limassol baut es Villen, Residenzen am Meer und Resorts auf Zypern und in Griechenland.',
  'Η Leptos Estates είναι ο φορέας πολυτελούς ανάπτυξης ακινήτων του Ομίλου Leptos, μιας κυπριακής οικογενειακής εταιρείας με παρουσία από το 1960. Με έδρα την Πάφο και γραφεία σε Λευκωσία και Λεμεσό, κατασκευάζει βίλες, κατοικίες δίπλα στη θάλασσα και resorts σε Κύπρο και Ελλάδα.',
  'Leptos Estates to deweloper luksusowych nieruchomości z Grupy Leptos, cypryjskiej firmy rodzinnej działającej od 1960 roku. Z siedzibą w Pafos i biurami w Nikozji i Limassol buduje wille, rezydencje nad morzem i kompleksy wypoczynkowe na Cyprze i w Grecji.',
  'Leptos Estates este dezvoltatorul imobiliar de lux al Grupului Leptos, o companie de familie cipriotă activă din 1960. Cu sediul la Paphos și birouri la Nicosia și Limassol, construiește vile, reședințe pe malul mării și resorturi în Cipru și Grecia.',
  'Leptos Estates является девелопером элитной недвижимости группы Leptos, кипрской семейной компании, работающей с 1960 года. Головной офис находится в Пафосе, офисы есть в Никосии и Лимасоле; компания строит виллы, резиденции у моря и курортные комплексы на Кипре и в Греции.',
  'ليبتوس إستيتس هي ذراع التطوير العقاري الفاخر في مجموعة ليبتوس، وهي شركة عائلية قبرصية تعمل منذ عام 1960. مقرها الرئيسي في بافوس ولها مكاتب في نيقوسيا وليماسول، وتبني فللاً ومساكن على البحر ومنتجعات في قبرص واليونان.',
);

